import { createRoot } from 'react-dom/client';
import { Toaster } from 'sonner';
import App from './App';
import './styles.css';

const root = createRoot(document.getElementById('root')!);
root.render(<><App /><Toaster richColors position="top-right" /></>);

:root { color-scheme: light; }
html, body, #root { height: 100%; }
body { margin: 0; background: #ffffff; color: #0a0a0a;
       font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
       -webkit-font-smoothing: antialiased; }

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useEffect, useRef, useState, useCallback } from 'react';
import { Play, Pause, RotateCcw } from 'lucide-react';

const W = 640;
const H = 380;
const PADDLE_W = 10;
const PADDLE_H = 70;
const BALL_R = 7;
const PADDLE_SPEED = 6;
const AI_SPEED = 4.2;

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const stateRef = useRef({
    py: H / 2 - PADDLE_H / 2,
    ay: H / 2 - PADDLE_H / 2,
    bx: W / 2,
    by: H / 2,
    bvx: 4,
    bvy: 2,
    keys: { up: false, down: false } as { up: boolean; down: boolean },
  });
  const [scores, setScores] = useState({ p: 0, a: 0 });
  const [running, setRunning] = useState(true);
  const [winner, setWinner] = useState<null | 'You' | 'AI'>(null);

  const serve = useCallback((dir: 1 | -1) => {
    const s = stateRef.current;
    s.bx = W / 2; s.by = H / 2;
    s.bvx = 4 * dir;
    s.bvy = (Math.random() * 4 - 2) || 2;
  }, []);

  const reset = useCallback(() => {
    setScores({ p: 0, a: 0 });
    setWinner(null);
    setRunning(true);
    serve(Math.random() < 0.5 ? 1 : -1);
  }, [serve]);

  // Input
  useEffect(() => {
    function onDown(e: KeyboardEvent) {
      const k = e.key.toLowerCase();
      if (k === 'arrowup' || k === 'w')   { stateRef.current.keys.up = true;   e.preventDefault(); }
      if (k === 'arrowdown' || k === 's') { stateRef.current.keys.down = true; e.preventDefault(); }
      if (k === ' ')                       { setRunning((r) => !r); e.preventDefault(); }
      if (k === 'r')                       { reset(); e.preventDefault(); }
    }
    function onUp(e: KeyboardEvent) {
      const k = e.key.toLowerCase();
      if (k === 'arrowup' || k === 'w')   stateRef.current.keys.up = false;
      if (k === 'arrowdown' || k === 's') stateRef.current.keys.down = false;
    }
    window.addEventListener('keydown', onDown);
    window.addEventListener('keyup', onUp);
    return () => {
      window.removeEventListener('keydown', onDown);
      window.removeEventListener('keyup', onUp);
    };
  }, [reset]);

  // Mouse control (canvas Y -> player paddle)
  useEffect(() => {
    const c = canvasRef.current; if (!c) return;
    function onMove(e: MouseEvent) {
      const c = canvasRef.current; if (!c) return;
      const r = c.getBoundingClientRect();
      const y = ((e.clientY - r.top) / r.height) * H - PADDLE_H / 2;
      stateRef.current.py = Math.max(0, Math.min(H - PADDLE_H, y));
    }
    c.addEventListener('mousemove', onMove);
    return () => c.removeEventListener('mousemove', onMove);
  }, []);

  // Main loop
  useEffect(() => {
    let raf = 0;
    function draw() {
      const c = canvasRef.current; if (!c) { raf = requestAnimationFrame(draw); return; }
      const ctx = c.getContext('2d'); if (!ctx) return;
      const s = stateRef.current;

      if (running && !winner) {
        if (s.keys.up)   s.py = Math.max(0, s.py - PADDLE_SPEED);
        if (s.keys.down) s.py = Math.min(H - PADDLE_H, s.py + PADDLE_SPEED);
        // AI: ease toward ball
        const target = s.by - PADDLE_H / 2;
        if (target < s.ay) s.ay = Math.max(0, s.ay - AI_SPEED);
        if (target > s.ay) s.ay = Math.min(H - PADDLE_H, s.ay + AI_SPEED);
        // Ball
        s.bx += s.bvx; s.by += s.bvy;
        if (s.by < BALL_R) { s.by = BALL_R; s.bvy *= -1; }
        if (s.by > H - BALL_R) { s.by = H - BALL_R; s.bvy *= -1; }
        // Paddle collisions
        if (s.bx - BALL_R < PADDLE_W && s.by > s.py && s.by < s.py + PADDLE_H && s.bvx < 0) {
          s.bvx = -s.bvx * 1.05;
          s.bvy += ((s.by - (s.py + PADDLE_H / 2)) / (PADDLE_H / 2)) * 2;
        }
        if (s.bx + BALL_R > W - PADDLE_W && s.by > s.ay && s.by < s.ay + PADDLE_H && s.bvx > 0) {
          s.bvx = -s.bvx * 1.05;
          s.bvy += ((s.by - (s.ay + PADDLE_H / 2)) / (PADDLE_H / 2)) * 2;
        }
        // Score
        if (s.bx < -10) {
          setScores((sc) => {
            const next = { ...sc, a: sc.a + 1 };
            if (next.a >= 7) setWinner('AI');
            return next;
          });
          serve(1);
        } else if (s.bx > W + 10) {
          setScores((sc) => {
            const next = { ...sc, p: sc.p + 1 };
            if (next.p >= 7) setWinner('You');
            return next;
          });
          serve(-1);
        }
      }

      // Render
      ctx.fillStyle = '#ffffff';      ctx.fillRect(0, 0, W, H);
      ctx.strokeStyle = '#eaeaea'; ctx.setLineDash([6, 8]);
      ctx.beginPath(); ctx.moveTo(W / 2, 0); ctx.lineTo(W / 2, H); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = '#76b900'; ctx.fillRect(0, s.py, PADDLE_W, PADDLE_H);
      ctx.fillStyle = '#feeeb2';  ctx.fillRect(W - PADDLE_W, s.ay, PADDLE_W, PADDLE_H);
      ctx.fillStyle = '#0a0a0a';
      ctx.beginPath(); ctx.arc(s.bx, s.by, BALL_R, 0, Math.PI * 2); ctx.fill();

      raf = requestAnimationFrame(draw);
    }
    raf = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(raf);
  }, [running, winner, serve]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#ffffff] p-4">
      <div className="rounded-2xl bg-[#f7f7f7] p-4 ring-1 ring-[#eaeaea] shadow-2xl">
        <div className="mb-3 flex items-center justify-between gap-6 text-sm">
          <div className="text-[#0a0a0a] font-semibold">Pong</div>
          <div className="flex gap-4 tabular-nums text-[#525252]">
            <span>You: <span className="text-[#76b900] font-semibold">{scores.p}</span></span>
            <span>AI:  <span className="text-[#feeeb2] font-semibold">{scores.a}</span></span>
            <span className="text-[#525252]">first to 7</span>
          </div>
        </div>
        <div className="relative" style={{ width: W, height: H }}>
          <canvas ref={canvasRef} width={W} height={H} className="rounded-lg block cursor-none" />
          {winner && (
            <div className="absolute inset-0 flex flex-col items-center justify-center rounded-lg bg-[#ffffff]/85 backdrop-blur-sm">
              <div className="text-2xl font-semibold text-[#0a0a0a] mb-1">{winner === 'You' ? 'You win' : 'AI wins'}</div>
              <div className="text-sm text-[#525252] mb-4">{scores.p} — {scores.a}</div>
              <button
                onClick={reset}
                className="rounded-full bg-[#76b900] px-5 py-2 text-sm font-medium text-[#0a0a0a] hover:bg-[#6caa00] inline-flex items-center gap-2"
              ><RotateCcw className="h-4 w-4" /> Rematch</button>
            </div>
          )}
        </div>
        <div className="mt-3 flex items-center justify-between gap-2 text-xs text-[#525252]">
          <span>Mouse or ↑↓ / W S · Space pause · R rematch</span>
          <div className="flex gap-2">
            <button
              onClick={() => setRunning((r) => !r)}
              disabled={!!winner}
              className="rounded-md bg-[#efefef] px-2 py-1 text-[#0a0a0a] hover:bg-[#e5e5e5] disabled:opacity-40 inline-flex items-center gap-1"
            >
              {running ? <><Pause className="h-3 w-3" />Pause</> : <><Play className="h-3 w-3" />Play</>}
            </button>
            <button
              onClick={reset}
              className="rounded-md bg-[#efefef] px-2 py-1 text-[#0a0a0a] hover:bg-[#e5e5e5] inline-flex items-center gap-1"
            ><RotateCcw className="h-3 w-3" /> Reset</button>
          </div>
        </div>
      </div>
    </div>
  );
}
